// Organization skill library (a fork rule): a skill its owner put in the library reaches this
// person's bots read only, gives way to a built-in skill of its name, and a bot's own new skill
// of the same name takes its place.
it("reads an organization library skill, read only, and never lets a bot change it", async () => {
  const builtin = BUILTIN_AGENT_SKILLS[0]!.name;
  prisma = makePrisma([
    {
      id: "library-1",
      spaceId: "ws-of-the-owner",
      userId: "organization-owner",
      name: "Team expenses",
      description: "File expenses the team way",
      content: buildSkillMd({ name: "Team expenses", description: "File expenses the team way", body: "Attach receipts." }),
      source: "user",
      files: { "receipts.md": "Keep every receipt." },
    },
    {
      id: "library-2",
      spaceId: "ws-of-the-owner",
      userId: "organization-owner",
      name: builtin,
      description: "Stands in for a built-in",
      content: buildSkillMd({ name: builtin, description: "Stands in for a built-in", body: "Not this." }),
      source: "user",
    },
  ]);
  prisma._library.push("library-1", "library-2");
  const listed = await listAgentSkillRecords(prisma as never, owner);
  expect(listed.find((skill) => skill.name === "Team expenses")).toMatchObject({
    source: "user",
    readOnly: true,
  });
  expect(listed.filter((skill) => skill.name === builtin)).toEqual([
    expect.objectContaining({ source: "builtin" }),
  ]);
  expect(
    await skillReadFromTool(prisma as never, owner, { name: "Team expenses", file: "receipts.md" }),
  ).toEqual({ name: "Team expenses", file: "receipts.md", content: "Keep every receipt." });
  expect(
    await skillUpdateFromTool(prisma as never, owner, { name: "Team expenses", body: "Mine" }),
  ).toHaveProperty("error");
  expect(await skillDeleteFromTool(prisma as never, owner, { name: "Team expenses" })).toHaveProperty(
    "error",
  );
  expect(
    await skillCreateFromTool(prisma as never, owner, {
      name: "Team expenses",
      description: "My own way",
    }),
  ).toMatchObject({ ok: true });
  const own = (await listAgentSkillRecords(prisma as never, owner)).filter(
    (skill) => skill.name === "Team expenses",
  );
  expect(own).toEqual([expect.objectContaining({ description: "My own way", readOnly: false })]);
});

